package com.ultras.bans.security;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.model.PunishmentType; import org.bukkit.entity.Player; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public final class SecurityService { private final ULTRASBansPlugin plugin; private final Map<UUID,Deque<Long>> hits=new ConcurrentHashMap<>(); public SecurityService(ULTRASBansPlugin p){plugin=p;} public void record(PunishmentType type,Player actor){if(actor==null||!plugin.configs().get("security.yml").getBoolean("enabled",true))return; var c=plugin.configs().get("security.yml"); if(!c.getStringList("tracked").contains(type.name()))return; long now=System.currentTimeMillis();long window=com.ultras.bans.utility.DurationUtil.parse(c.getString("window","20s"))*1000;Deque<Long> q=hits.computeIfAbsent(actor.getUniqueId(),x->new ArrayDeque<>());synchronized(q){q.add(now);while(!q.isEmpty()&&now-q.peekFirst()>window)q.removeFirst();if(q.size()>=c.getInt("actions",5)){plugin.getServer().getOnlinePlayers().stream().filter(p->p.hasPermission("ultrasbans.admin")).forEach(p->p.sendMessage(com.ultras.bans.utility.Text.c("<yellow>⚠ ᴜʟᴛʀᴀs | Security threshold detected for "+actor.getName()+".</yellow>")));String action=c.getString("after-threshold.action","NONE");if(action.equalsIgnoreCase("REMOVE_OP"))actor.setOp(false); if(action.equalsIgnoreCase("LOCK_STAFF")) actor.addAttachment(plugin,"ultrasbans.*",false); plugin.database().staffAction(actor.getName(),actor.getUniqueId(),"SECURITY_THRESHOLD",actor.getName(),"count="+q.size());q.clear();}}}}
